public void transfer(Connection conn, String from, String to, BigDecimal amount)
        throws SQLException {
    if (amount.signum() <= 0) {                      // a negative amount would reverse the transfer
        throw new IllegalArgumentException("Amount must be positive");
    }
    boolean oldAutoCommit = conn.getAutoCommit();
    conn.setAutoCommit(false);                       // BEGIN
    try (PreparedStatement debit = conn.prepareStatement(
             "UPDATE accounts SET balance = balance - ? WHERE id = ? AND balance >= ?");
         PreparedStatement credit = conn.prepareStatement(
             "UPDATE accounts SET balance = balance + ? WHERE id = ?")) {
        debit.setBigDecimal(1, amount);
        debit.setString(2, from);
        debit.setBigDecimal(3, amount);
        if (debit.executeUpdate() != 1) {
            throw new SQLException("Insufficient funds or unknown account");
        }
        credit.setBigDecimal(1, amount);
        credit.setString(2, to);
        if (credit.executeUpdate() != 1) {
            throw new SQLException("Unknown target account");
        }
        conn.commit();                               // durable from here on
    } catch (SQLException e) {
        conn.rollback();                             // atomicity: undo the debit
        throw e;
    } finally {
        conn.setAutoCommit(oldAutoCommit);
    }
}

CREATE TABLE departments (
  dept_id   VARCHAR(10)  PRIMARY KEY,
  dept_name VARCHAR(100) NOT NULL
);

CREATE TABLE students (
  student_id INT          PRIMARY KEY,        -- chosen candidate key
  nid        VARCHAR(20)  NOT NULL UNIQUE,    -- alternate key
  email      VARCHAR(100) NOT NULL UNIQUE,    -- alternate key
  phone      VARCHAR(15)  UNIQUE,             -- unique key, NULL allowed
  name       VARCHAR(100) NOT NULL,           -- not a key: names repeat
  dept_id    VARCHAR(10)  NOT NULL,
  FOREIGN KEY (dept_id) REFERENCES departments (dept_id)   -- foreign key
);

CREATE TABLE enrollments (
  student_id  INT         NOT NULL,
  course_code VARCHAR(10) NOT NULL,
  grade       VARCHAR(2),
  PRIMARY KEY (student_id, course_code),      -- composite key
  FOREIGN KEY (student_id) REFERENCES students (student_id)
);

