-- Secondary (non-clustered) index for lookups by email
CREATE INDEX idx_customers_email ON customers (email);

-- Composite index: equality column first, then the sort/range column
CREATE INDEX idx_orders_customer_created ON orders (customer_id, created_at);

-- Seek on customer_id; rows come out already sorted by created_at (no sort step).
-- SELECT * still fetches the remaining columns of those 10 rows from the table.
EXPLAIN
SELECT * FROM orders
WHERE customer_id = 42
ORDER BY created_at DESC
LIMIT 10;

-- Not sargable: the function hides created_at from an index on it
-- SELECT * FROM orders WHERE YEAR(created_at) = 2024;
-- Sargable rewrite: a plain range on the column
SELECT * FROM orders
WHERE created_at >= '2024-01-01' AND created_at < '2025-01-01';

