-- Normalized read: 2 joins + aggregation on every page load
SELECT o.order_id, c.name AS customer, SUM(i.qty * i.unit_price) AS total
FROM orders o
JOIN customers c   ON c.cust_id = o.cust_id
JOIN order_items i ON i.order_id = o.order_id
GROUP BY o.order_id, c.name
ORDER BY o.order_id;

-- Denormalized: store the customer name and order total on orders
ALTER TABLE orders ADD COLUMN customer_name VARCHAR(100);
ALTER TABLE orders ADD COLUMN total_amount  DECIMAL(12,2) NOT NULL DEFAULT 0;

-- Backfill the new columns once from the source tables
UPDATE orders
SET customer_name = (SELECT c.name FROM customers c WHERE c.cust_id = orders.cust_id),
    total_amount  = (SELECT COALESCE(SUM(i.qty * i.unit_price), 0)
                     FROM order_items i WHERE i.order_id = orders.order_id);

-- Read becomes a single-table lookup
SELECT order_id, customer_name, total_amount FROM orders WHERE cust_id = 'C1';

-- Every write must now keep the copy in sync - in the SAME transaction
START TRANSACTION;
INSERT INTO order_items (order_id, prod_id, qty, unit_price) VALUES (101, 'P3', 1, 900);
UPDATE orders SET total_amount = total_amount + 1 * 900 WHERE order_id = 101;
COMMIT;

