-- VIEW: a saved SELECT used like a table (hides columns, pre-joins)
CREATE VIEW customer_orders AS
SELECT c.id AS customer_id, c.full_name, o.id AS order_id, o.status, o.placed_at
FROM customer c
JOIN orders o ON o.customer_id = c.id;

SELECT * FROM customer_orders WHERE customer_id = 42;

-- TRIGGER: audit every balance change automatically (MySQL syntax)
CREATE TRIGGER trg_accounts_audit
AFTER UPDATE ON accounts
FOR EACH ROW
INSERT INTO account_audit (account_id, old_balance, new_balance, changed_at)
VALUES (OLD.id, OLD.balance, NEW.balance, NOW());

-- STORED PROCEDURE: a whole transfer in one call (MySQL syntax)
DELIMITER //
CREATE PROCEDURE transfer_money(IN p_from INT, IN p_to INT, IN p_amount DECIMAL(12,2))
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;
  IF p_amount <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Amount must be positive';
  END IF;
  START TRANSACTION;
  UPDATE accounts SET balance = balance - p_amount
  WHERE id = p_from AND balance >= p_amount;
  IF ROW_COUNT() = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Insufficient funds or unknown account';
  END IF;
  UPDATE accounts SET balance = balance + p_amount WHERE id = p_to;
  IF ROW_COUNT() = 0 THEN   -- unknown target: without this check the debit commits and the money vanishes
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unknown target account';
  END IF;
  COMMIT;
END //
DELIMITER ;

CALL transfer_money(1, 2, 500.00);

-- DELETE: remove chosen rows (DML) - WHERE allowed, triggers fire, can roll back
START TRANSACTION;
DELETE FROM employees WHERE dept = 'Sales';
ROLLBACK;                    -- the two Sales rows are back

-- TRUNCATE: remove ALL rows fast, keep the empty table
TRUNCATE TABLE employees;    -- PostgreSQL: TRUNCATE employees RESTART IDENTITY;

-- DROP: remove the table itself (structure, indexes, triggers, grants)
DROP TABLE employees;        -- or DROP TABLE IF EXISTS employees;
